//! Checks `colour_map` against colours QuPath's own colour map produced.
//!
//! `parity/java/ColourMap.java` calls `ColorMaps.getDefaultColorMap().getColor`
//! — the per-object half of a measurement map, once the range is chosen — over
//! four ranges, and records the answers in `parity/fixtures/ColourMap.json`.
//! This asserts [`colour_map::INFERNO`] indexed by [`colour_map::index`] gives
//! the same colour for every recorded value, bit for bit.
//!
//! It is what makes "QuPath's Inferno, indexed QuPath's way" a claim: the table
//! was generated by reproducing `DefaultColorMap`'s constructor in a script, and
//! a script agreeing with a reading of the Java is not evidence here
//! (`CONTRIBUTING.md`).
//!
//! # The one recorded disagreement
//!
//! `getColor(+∞)` comes back as the **first** colour: the Java rounds to a
//! `long` and casts to `int`, which wraps `Long.MAX_VALUE` to −1, and the clamp
//! then takes it to entry 0. [`colour_map::index`] clamps before casting and
//! gives the last. It is asserted below as a difference, so it cannot quietly
//! become an agreement or a different disagreement. It does not reach a user of
//! either program the same way: QuPath's `MeasurementMapper` replaces an
//! infinite value with the data's maximum or minimum before this call (a
//! reading of `getUsefulValue`, not recorded — it lives in `qupath-gui-fx`), and
//! this project's range never contains an infinity.

use qupath_viewer::colour_map::{self, INFERNO};

const FIXTURE: &str = include_str!("../../../parity/fixtures/ColourMap.json");

/// One recorded range: its ends and the value/colour pairs taken over it.
struct Recorded {
    name: String,
    min: f32,
    max: f32,
    values: Vec<f32>,
    colours: Vec<u32>,
}

/// The quoted strings after `"key": [` up to the closing bracket.
fn strings_after<'a>(text: &'a str, key: &str) -> Vec<&'a str> {
    let start = text.find(&format!("\"{key}\": [")).expect(key) + key.len() + 5;
    let end = start + text[start..].find(']').expect("a closing bracket");
    text[start..end]
        .split(',')
        .map(|item| item.trim().trim_matches('"'))
        .filter(|item| !item.is_empty())
        .collect()
}

/// The quoted string after `"key": `.
fn string_after<'a>(text: &'a str, key: &str) -> &'a str {
    let start = text.find(&format!("\"{key}\": \"")).expect(key) + key.len() + 5;
    let end = start + text[start..].find('"').expect("a closing quote");
    &text[start..end]
}

/// `Float.toString`'s spellings, as `f32`. Every finite one reads back exactly.
fn float(text: &str) -> f32 {
    match text {
        "NaN" => f32::NAN,
        "Infinity" => f32::INFINITY,
        "-Infinity" => f32::NEG_INFINITY,
        _ => text.parse().expect("a float"),
    }
}

fn ranges() -> Vec<Recorded> {
    FIXTURE
        .split("{\"name\": ")
        .skip(1)
        .map(|block| Recorded {
            name: block[1..block[1..].find('"').expect("a name") + 1].to_owned(),
            min: float(string_after(block, "min")),
            max: float(string_after(block, "max")),
            values: strings_after(block, "values")
                .into_iter()
                .map(float)
                .collect(),
            colours: strings_after(block, "colours")
                .into_iter()
                .map(|hex| u32::from_str_radix(hex, 16).expect("hex"))
                .collect(),
        })
        .collect()
}

#[test]
fn the_default_map_is_inferno_and_every_range_was_recorded() {
    // What makes the assertions below about the table this module ships
    // rather than about some other map QuPath happened to default to.
    assert_eq!(string_after(FIXTURE, "map"), "Inferno");
    let ranges = ranges();
    let names: Vec<&str> = ranges.iter().map(|r| r.name.as_str()).collect();
    assert_eq!(names, ["sweep", "ties", "reversed", "no width"]);
    for range in &ranges {
        assert_eq!(range.values.len(), range.colours.len(), "{}", range.name);
        assert!(!range.values.is_empty(), "{} recorded nothing", range.name);
    }
    // The sweep covers the whole table, so no entry is unchecked, and the ties
    // are one per entry.
    let sweep = &ranges[0];
    let mut seen: Vec<u32> = sweep.colours.clone();
    seen.sort_unstable();
    seen.dedup();
    let mut table = INFERNO.to_vec();
    table.sort_unstable();
    table.dedup();
    assert_eq!(seen, table, "the sweep did not reach every entry");
    assert_eq!(ranges[1].values.len(), 256);
}

#[test]
fn every_recorded_colour_is_the_table_entry_the_index_picks() {
    let mut compared = 0;
    for range in ranges() {
        for (&value, &expected) in range.values.iter().zip(&range.colours) {
            if value == f32::INFINITY {
                continue; // The recorded disagreement; see the test below.
            }
            let index =
                colour_map::index(f64::from(value), f64::from(range.min), f64::from(range.max));
            assert_eq!(
                INFERNO[index], expected,
                "{}: value {value} in {}..{} gave entry {index} ({:06x}), QuPath {expected:06x}",
                range.name, range.min, range.max, INFERNO[index],
            );
            compared += 1;
        }
    }
    assert!(compared > 2000, "only {compared} colours compared");
}

#[test]
fn positive_infinity_is_the_one_recorded_difference() {
    let sweep = ranges().remove(0);
    let at = sweep
        .values
        .iter()
        .position(|&v| v == f32::INFINITY)
        .expect("the sweep records +infinity");
    // QuPath: the first colour, by `(int)` of `Long.MAX_VALUE`.
    assert_eq!(sweep.colours[at], INFERNO[0]);
    // Here: the last, because a value above the range is drawn as the top.
    assert_eq!(
        colour_map::index(f64::INFINITY, f64::from(sweep.min), f64::from(sweep.max)),
        INFERNO.len() - 1
    );
}
